def dpo_implicit_reward(logp_policy: float, logp_ref: float, beta: float) -> float:
    """DPO's implicit reward: beta * (logp_policy - logp_ref)."""
    drift = logp_policy - logp_ref
    return round(beta * drift, 4)

print(dpo_implicit_reward(-12.4, -15.1, 0.1))

def dpo_implicit_reward(logp_policy: float, logp_ref: float, beta: float) -> float:
    drift = logp_policy - logp_ref
    return round(beta * drift, 4)

def reward_pair(logp_policy_chosen: float, logp_ref_chosen: float, logp_policy_rejected: float, logp_ref_rejected: float, beta: float) -> list:
    """Implicit reward for both the chosen and rejected completion."""
    r_chosen = dpo_implicit_reward(logp_policy_chosen, logp_ref_chosen, beta)
    r_rejected = dpo_implicit_reward(logp_policy_rejected, logp_ref_rejected, beta)
    return [r_chosen, r_rejected]

print(reward_pair(-12.4, -15.1, -18.7, -16.0, 0.1))
